import { DesignSyncError } from "../core/errors.js";
import { atomicJson } from "./state.js";
import { readFile, copyFile } from "node:fs/promises";
export type Migration = {
  from: number;
  to: number;
  apply: (value: Record<string, unknown>) => Record<string, unknown>;
};
export function migrateValue(
  value: Record<string, unknown>,
  target: number,
  steps: Migration[],
) {
  const current = value.version;
  if (
    typeof current !== "number" ||
    !Number.isInteger(current) ||
    current > target
  )
    throw new DesignSyncError(
      "UNSUPPORTED_SCHEMA",
      "Unsupported schema version. Upgrade Design Sync or restore supported state.",
    );
  let result = structuredClone(value);
  while (result.version !== target) {
    const step = steps.find(
      (s) => s.from === result.version && s.to === s.from + 1,
    );
    if (!step)
      throw new DesignSyncError(
        "UNSUPPORTED_SCHEMA",
        `No migration from schema ${String(result.version)} is available.`,
      );
    result = {
      ...result,
      ...step.apply(structuredClone(result)),
      version: step.to,
    };
  }
  return result;
}
export async function migrateFile(
  file: string,
  target: number,
  steps: Migration[],
  apply: boolean,
) {
  const original = JSON.parse(await readFile(file, "utf8")) as Record<
    string,
    unknown
  >;
  const migrated = migrateValue(original, target, steps);
  if (original.version === target) return { file, changed: false };
  const backup = `${file}.backup-${Date.now()}`;
  if (apply) {
    await copyFile(file, backup);
    await atomicJson(file, migrated);
  }
  return { file, changed: true, applied: apply, ...(apply ? { backup } : {}) };
}

import path from "node:path";
import { access, realpath, readFile } from "node:fs/promises";
import { execFileSync } from "node:child_process";
import { DesignSyncError } from "../core/errors.js";
import { hash } from "../core/hashing.js";
export async function exists(file: string) {
  try {
    await access(file);
    return true;
  } catch {
    return false;
  }
}
export async function resolveRoot(
  explicit?: string,
  cwd = process.cwd(),
): Promise<string> {
  if (explicit) return realpath(path.resolve(cwd, explicit));
  let current = path.resolve(cwd),
    packageRoot: string | undefined;
  while (true) {
    if (await exists(path.join(current, ".design-sync/config.json")))
      return realpath(current);
    if (!packageRoot && (await exists(path.join(current, "package.json"))))
      packageRoot = current;
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  try {
    return await realpath(
      execFileSync("git", ["rev-parse", "--show-toplevel"], {
        cwd,
        encoding: "utf8",
        stdio: ["ignore", "pipe", "ignore"],
      }).trim(),
    );
  } catch {
    return realpath(packageRoot ?? cwd);
  }
}
export function normalizePath(file: string): string {
  const value = file.replaceAll("\\", "/");
  const normalized = path.posix.normalize(value);
  if (
    !value ||
    value.includes("\0") ||
    path.posix.isAbsolute(value) ||
    /^[A-Za-z]:/.test(value) ||
    normalized === ".." ||
    normalized.startsWith("../") ||
    normalized === "."
  )
    throw new DesignSyncError(
      "INVALID_PATH",
      `Path must be repository-root-relative: ${file}`,
    );
  return normalized;
}
export async function safeFile(root: string, file: string): Promise<string> {
  const target = path.resolve(root, normalizePath(file));
  const resolved = await realpath(target);
  const relative = path.relative(await realpath(root), resolved);
  if (
    relative === ".." ||
    relative.startsWith(`..${path.sep}`) ||
    path.isAbsolute(relative)
  )
    throw new DesignSyncError(
      "INVALID_PATH",
      `Path escapes repository through a symlink: ${file}`,
    );
  return resolved;
}
export async function codeRevision(
  root: string,
  files: string[],
): Promise<string> {
  const paths = [...new Set(files.map(normalizePath))].sort();
  if (!paths.length)
    throw new DesignSyncError(
      "INVALID_MAPPING",
      "Implementation requires at least one file.",
    );
  const contents = [];
  for (const file of paths) {
    try {
      // Latin-1 preserves arbitrary bytes while allowing only CRLF normalization.
      const bytes = await readFile(await safeFile(root, file));
      contents.push({
        path: file,
        contents: Buffer.from(
          bytes.toString("latin1").replaceAll("\r\n", "\n"),
          "latin1",
        ).toString("base64"),
      });
    } catch (error) {
      if (error instanceof DesignSyncError) throw error;
      throw new DesignSyncError(
        "MISSING_IMPLEMENTATION_FILE",
        `Cannot read implementation file ${file}. Restore the file or replace the mapping.`,
        { file },
      );
    }
  }
  return hash(contents);
}

import path from "node:path";
import { mkdir, readFile, writeFile, rename, unlink } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { z } from "zod";
import { DesignSyncError } from "../core/errors.js";
import {
  configSchema,
  manifestSchema,
  snapshotSchema,
  type Config,
  type Manifest,
  type NodeRecord,
} from "../core/schemas.js";
import { designRevision, identity } from "../core/hashing.js";
import { safeFile } from "./paths.js";
export const statePath = (root: string, file: string) =>
  path.join(root, ".design-sync", file);
export async function readJson<T>(
  file: string,
  schema: z.ZodType<T>,
): Promise<T> {
  try {
    return schema.parse(JSON.parse(await readFile(file, "utf8")));
  } catch (error) {
    throw new DesignSyncError(
      "INVALID_STATE",
      `Cannot read or validate ${file}. Check its schema version and JSON; run design:migrate for supported upgrades.`,
      {
        cause:
          error instanceof z.ZodError
            ? error.issues
                .map((i) => `${i.path.join(".")}: ${i.message}`)
                .join("; ")
            : ((error as NodeJS.ErrnoException).code ?? "Invalid JSON"),
      },
    );
  }
}
export async function atomicJson(file: string, value: unknown) {
  await mkdir(path.dirname(file), { recursive: true });
  const temporary = `${file}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporary, JSON.stringify(value, null, 2) + "\n", {
      flag: "wx",
    });
    await rename(temporary, file);
  } finally {
    await unlink(temporary).catch(() => {});
  }
}
export async function withLock<T>(
  root: string,
  fn: () => Promise<T>,
): Promise<T> {
  await mkdir(statePath(root, ""), { recursive: true });
  const lock = statePath(root, "write.lock");
  try {
    await writeFile(
      lock,
      JSON.stringify({ pid: process.pid, startedAt: new Date().toISOString() }),
      { flag: "wx" },
    );
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    throw new DesignSyncError(
      "STATE_LOCKED",
      `Another operation owns ${lock}. If it crashed, verify the recorded process has stopped before removing this lock.`,
    );
  }
  try {
    return await fn();
  } finally {
    await unlink(lock);
  }
}
export async function loadState(
  root: string,
): Promise<{ config: Config; manifest: Manifest }> {
  const config = await readJson(statePath(root, "config.json"), configSchema);
  const manifest = await readJson(
    statePath(root, "manifest.json"),
    manifestSchema,
  );
  for (const [key, record] of Object.entries(manifest.nodes)) {
    if (
      key !== identity(record.reference) ||
      record.reference.fileKey !== config.figma.fileKey
    )
      throw new DesignSyncError(
        "INVALID_MANIFEST",
        "Manifest identity or fileKey does not match configuration. Restore the original configuration or explicitly migrate project state.",
      );
  }
  return { config, manifest };
}
export async function loadBaseline(root: string, record: NodeRecord) {
  if (!record.baseline) return undefined;
  const expectedPrefix = `snapshots/${identity(record.reference)}/`;
  if (!record.baseline.snapshot.startsWith(expectedPrefix))
    throw new DesignSyncError(
      "CORRUPT_SNAPSHOT",
      "Snapshot path does not match node identity.",
    );
  const file = await safeFile(statePath(root, ""), record.baseline.snapshot);
  const snapshot = await readJson(file, snapshotSchema);
  if (
    identity(snapshot.reference) !== identity(record.reference) ||
    snapshot.node.id !== record.reference.nodeId ||
    designRevision(snapshot.node) !== record.baseline.designRevision ||
    snapshot.designRevision !== record.baseline.designRevision
  )
    throw new DesignSyncError(
      "CORRUPT_SNAPSHOT",
      "Snapshot identity or hash does not match the baseline. Restore the committed snapshot.",
    );
  return snapshot;
}
